/// @pob Modules/ConfigOptions.lua:117-130 h=ed82db17
/// `ConfigOptions[278].apply` (also: ConfigOptions[279].apply, ConfigOptions[280].apply, ConfigOptions[281].apply, ConfigOptions[283].apply, ConfigOptions[284].apply, ConfigOptions[285].apply)…
///
/// `local function mapAffixDropDownFunction(val, modList, enemyModList, build)`. The affix
/// `apply` is dispatched through `MODMAP_APPLY` (calc doc §8.1) with the call shape
/// `affixData.type` selects; `build.configTab.varControls['multiplierMapModTier']` is the
/// control-state table of the model (a missing control raises Lua's index error; CCR-0037).
pub(crate) fn opt_278_apply(
    val: &Val,
    modList: &ModList,
    enemyModList: &ModList,
    build: &BuildRef,
) {
    use crate::modules::mod_map::{ModMapApply, MODMAP_APPLY};
    // L118
    if !val_eq_str(val, "NONE") {
        // L119 (`data.mapMods.AffixData[val] or {}`: a non-string key finds nothing)
        let affixData = match val {
            Val::Str(s) => data().mapMods.AffixData.get(&Name::from(&**s)),
            _ => None,
        };
        // L120
        let Some(affixData) = affixData else { return };
        let Some(apply) = &affixData.apply else {
            return;
        };
        let configTab = &build.configTab;
        // `affixData.values` (the call shapes only read it)
        let values = || {
            let t = Table::new();
            for v in &affixData.values {
                t.push(Val::from_value(v));
            }
            t
        };
        // `(1 + (build.configTab.input['multiplierMapModEffect'] or 0) / 100)`
        let mapModEffect = || {
            1.0 + lor(configTab.input.get(n!("multiplierMapModEffect")), || {
                Val::from(0.0)
            })
            .num()
                / 100.0
        };
        // `4 - (build.configTab.varControls['multiplierMapModTier'].selIndex or 1)`
        let tier = || {
            4.0 - lor(
                configTab
                    .varControls
                    .get(n!("multiplierMapModTier"))
                    .get(n!("selIndex")),
                || Val::from(1.0),
            )
            .num()
        };
        let f = match MODMAP_APPLY.get(apply.id.as_str()) {
            Some(row) => row.f,
            None => {
                let () = unported!("Data/ModMap.lua (apply not in the registry)");
                return;
            }
        };
        let ty = affixData.r#type.as_ref().map(|t| t.as_str());
        // L121
        if ty == Some("check") {
            // L122
            let ModMapApply::check(f) = f else {
                lua_error!(
                    "mapAffixDropDownFunction: {} is not a `check` apply",
                    apply.id
                )
            };
            f(val, mapModEffect(), modList, enemyModList);
        } else if ty == Some("list") {
            // L124 (arguments left to right: the tier is read first)
            let ModMapApply::list(f) = f else {
                lua_error!(
                    "mapAffixDropDownFunction: {} is not a `list` apply",
                    apply.id
                )
            };
            let tier = tier();
            f(tier, mapModEffect(), &values(), modList, enemyModList);
        } else if ty == Some("count") {
            // L126
            let ModMapApply::count(f) = f else {
                lua_error!(
                    "mapAffixDropDownFunction: {} is not a `count` apply",
                    apply.id
                )
            };
            let tier = tier();
            f(
                tier,
                100.0,
                mapModEffect(),
                &values(),
                modList,
                enemyModList,
            );
        }
    }
}

