/// @pob Modules/ConfigOptions.lua:155-157 h=6ab74a80
/// `ConfigOptions[6].apply`
pub(crate) fn opt_6_apply(val: &Val, modList: &ModList, enemyModList: &ModList, _build: &BuildRef) {
    // L156
    modList.NewMod(
        n!("SkillData"),
        LIST,
        vtab(
            vec![],
            vec![
                (n!("key"), Value::from("corpseLife")),
                (n!("value"), Value::from(val_value(&val))),
            ],
        ),
        "Config",
        0,
        0,
        &[],
    );
}

