/// @pob Modules/ConfigOptions.lua:160-170 h=9dca2e8b
/// `ConfigOptions[7].apply`
pub(crate) fn opt_7_apply(val: &Val, modList: &ModList, enemyModList: &ModList, _build: &BuildRef) {
    let mut val: Val = val.clone(); // Lua reassigns the parameter
                                    // L161
    if matches!(val, Val::Bool(_)) {
        // Backwards compatibility with older versions that set this condition as a boolean
        // L163
        val = if val.truthy() {
            Val::from(1.0)
        } else {
            Val::from(0.0)
        };
    }
    // L165
    let mut sanitizedValue = m_max(0.0, val.num());
    // L166
    modList.NewMod(
        n!("Multiplier:StationarySeconds"),
        BASE,
        sanitizedValue,
        "Config",
        0,
        0,
        &[],
    );
    // L167
    if (sanitizedValue > 0.0) {
        // L168
        modList.NewMod(n!("Condition:Stationary"), FLAG, true, "Config", 0, 0, &[]);
    }
}

