/// `ConfigOptions[254].apply`
pub(crate) fn opt_254_apply(
    val: &Val,
    modList: &ModList,
    enemyModList: &ModList,
    build: &BuildRef,
) {
    // `build.configTab.varControls['enemyRadius']:SetPlaceholder(n, false)` on the model's
    // control-state table (CCR-0037; CCR-0038: `ConfigTab::SetPlaceholder`).
    let SetPlaceholder = |text: f64| {
        build
            .configTab
            .SetPlaceholder(build, n!("enemyRadius"), &Val::Num(text), false)
    };
    // L788
    if val_eq_str(&val, "Small") {
        // L789
        SetPlaceholder(2.0);
        // L790
        modList.NewMod(n!("EnemyRadius"), BASE, 2.0, "Config", 0, 0, &[]);
    } else if val_eq_str(&val, "Medium") {
        // L792
        SetPlaceholder(3.0);
        // L793
        modList.NewMod(n!("EnemyRadius"), BASE, 3.0, "Config", 0, 0, &[]);
    } else if val_eq_str(&val, "Large") {
        // L795
        SetPlaceholder(5.0);
        // L796
        modList.NewMod(n!("EnemyRadius"), BASE, 5.0, "Config", 0, 0, &[]);
    } else if val_eq_str(&val, "Huge") {
        // L798
        SetPlaceholder(11.0);
        // L799
        modList.NewMod(n!("EnemyRadius"), BASE, 11.0, "Config", 0, 0, &[]);
    }
}

